-- The Data61 brand is retired: replace the Data61 logo & link of the default footer copyright
-- item (added by V1_8) with the CSIRO logo & website.
-- Each change only applies while the item still has the default value, so a customised footer is kept.

-- the logo: the CSIRO logo (63x62 PNG, shown 36px high by the `csiro-logo` class) & its alt text
UPDATE public.content
SET content = (
    content::jsonb || jsonb_build_object(
        'logoSrc', 'data:image/png;base64,',
        'logoClassName', CASE
            WHEN content::jsonb ->> 'logoClassName' = 'data61-logo' THEN 'csiro-logo'
            ELSE COALESCE(content::jsonb ->> 'logoClassName', '')
        END,
        'logoAlt', COALESCE(NULLIF(content::jsonb ->> 'logoAlt', ''), 'CSIRO')
    )
)::text
WHERE id = 'footer/copyright/csiro'
    AND type = 'application/json'
    AND content::jsonb ->> 'logoSrc' = 'data:image/png;base64,';

-- the logo link
UPDATE public.content
SET content = jsonb_set(content::jsonb, '{href}', '"https://www.csiro.au/"')::text
WHERE id = 'footer/copyright/csiro'
    AND type = 'application/json'
    AND content::jsonb ->> 'href' = 'https://data61.csiro.au/';
